# ──────────────────────────────────────────────────────────────────────────────
# config.py — USER-MANAGED hyperparameters & runtime settings
# ──────────────────────────────────────────────────────────────────────────────
# This file is **NOT** auto-generated. It is safe to edit by hand.
#
# The auto-generated system prompts and schema constants live in
# ``agent/prompts.py`` (regenerated by ``python -m schema.gen_system_prompt``
# from the live Neo4j schema).
# Keeping the two files separate prevents ``setup_project.py`` from
# overwriting the LLM configuration / pipeline knobs every time the schema
# is re-derived.
#
# Layout
# ──────
#   1. LLM configuration (per pipeline stage)
#   2. Runtime constants (sampling, validation, threading)
#   3. NER pipeline mode
# ──────────────────────────────────────────────────────────────────────────────

import os
from dataclasses import dataclass
from typing import Optional

from component_names import env_flag as _component_flag

# ──────────────────────────────────────────────────────────────────────────────
# LLM configuration  (per pipeline stage)
# ──────────────────────────────────────────────────────────────────────────────
# Each pipeline stage has its own LLM "slot" so experiments can mix providers
# (e.g. one provider for NER, another for Cypher generation) without code changes.
#
# Schema for every entry:
#   {
#     "provider":    "openai" | "azure" | "anthropic" | "hf_compatible" | "auto",
#     "model":       <model-name | deployment | MODEL_REGISTRY key>,
#     "temperature": <float>,         # optional, default 0
#     # Anything else (max_tokens, top_p, …) is forwarded verbatim to the
#     # chat-model constructor.
#   }
#
# When ``provider == "hf_compatible"`` the ``model`` field is interpreted as
# a key into ``MODEL_REGISTRY`` (see below).  The factory looks the key up to
# get the actual base_url / api_key / model id that should be sent to the
# OpenAI-compatible server.
#
# ``agent_helper.build_llm(**LLM_CONFIG)`` consumes these dicts and returns a
# concrete ``BaseChatModel`` — see ``agent_helper.ner_llm`` / ``qa_llm`` /
# ``cypher_llm`` for the resolved singletons.
#
# Examples
# --------
#   NER_LLM_CONFIG    = {"provider": "openai",        "model": "gpt-5.6-terra"}
#   CYPHER_LLM_CONFIG = {"provider": "anthropic",     "model": "claude-sonnet-5"}
#   QA_LLM_CONFIG     = {"provider": "hf_compatible", "model": "deepseek-v4.1-flash-deepinfra"}
# ──────────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────────
# MODEL_REGISTRY — OpenAI-compatible endpoints for open-weights models
# ──────────────────────────────────────────────────────────────────────────────
# Every entry describes one OpenAI-compatible HTTP endpoint.  The factory in
# ``agent_helper`` instantiates an openai-SDK-compatible chat client
# (LangChain's ``ChatOpenAI``) pointed at ``base_url`` with credentials from
# ``os.environ[api_key_env]`` and sends ``model`` in the request body.
# Hosted inference providers and self-hosted servers (vLLM, TGI, …) all expose
# the same ``/v1/chat/completions`` interface, so one ``hf_compatible``
# provider covers them; only ``base_url``, the key and the model id differ.
#
# To add an endpoint: add an entry below (a unique key, the endpoint URL,
# the name of the env var holding its key, and the model id the endpoint
# expects) and reference the key from a preset or a stage config with
# ``provider="hf_compatible"``.
# ──────────────────────────────────────────────────────────────────────────────

MODEL_REGISTRY: dict = {
    # DeepSeek V4.1 Flash (MIT weights) served by DeepInfra; the preset below
    # switches its thinking mode off and caps the output at 4,096 tokens.
    "deepseek-v4.1-flash-deepinfra": {
        "base_url":    "https://api.deepinfra.com/v1/openai",
        "api_key_env": "DEEPINFRA_API_KEY",
        "model":       "deepseek-ai/DeepSeek-V4.1-Flash",
    },
}




# ── Generator LLM: presets + the eval receiver ───────────────────────────────
# One name selects the generator LLM for all three stages (NER / Cypher / QA).
# Edit it in eval_config.py (``GENERATOR_LLM = "gpt-5.6-terra"``) — the control
# panel — never here and never in .env, which holds API keys only. eval_run
# injects the chosen name into the worker as the GENERATOR_LLM env var, the
# same way it passes METHOD; the name is also what appears in the run
# directory (``cyanchor_fl@gpt-5.6-terra``), so a sweep never mixes models.
#
# provider "openai" / "anthropic" call the vendor directly; "hf_compatible"
# routes through an OpenAI-compatible endpoint described in MODEL_REGISTRY.
# An optional "params" dict is passed to the chat-model constructor verbatim
# (e.g. {"reasoning_effort": "medium"}); the builders already choose safe
# defaults per model family, so most presets need none.
MODEL_PRESETS: dict = {
    # ── GPT family (OpenAI API; reasoning effort "none" — see agent_helper) ──
    "gpt-5.6-terra":    {"provider": "openai",        "model": "gpt-5.6-terra"},   # primary backbone
    "gpt-5.6-luna":     {"provider": "openai",        "model": "gpt-5.6-luna"},    # cheaper tier
    # ── Claude (Anthropic API; temperature is rejected and thinking is switched
    #    off for this generation — see agent_helper._anthropic_generation_kwargs) ──
    "claude-sonnet-5":  {"provider": "anthropic",     "model": "claude-sonnet-5"},
    # ── open weights (DeepInfra, OpenAI-compatible). max_tokens is set because the
    #    host otherwise reserves the model's whole context as the output budget and
    #    rejects the request; the thinking switch keeps the model a plain generator. ──
    "deepseek-v4.1-flash": {"provider": "hf_compatible", "model": "deepseek-v4.1-flash-deepinfra",
                            "params": {"max_tokens": 4096, "extra_body": {"thinking": {"type": "disabled"}}}},
}

# ⚙ eval receiver — edit GENERATOR_LLM in the eval_config panel, not here.
GENERATOR_LLM = os.getenv("GENERATOR_LLM") or None


def resolve_preset(name: str) -> dict:
    """Preset name -> ``{"provider", "model"}``. Unknown names fail loudly with
    the list of valid ones; a silent fallback here would put the wrong model
    behind a directory that claims another."""
    if name in MODEL_PRESETS:
        return dict(MODEL_PRESETS[name])
    raise KeyError(f"GENERATOR_LLM={name!r} is not a preset. Known presets: "
                   + ", ".join(sorted(MODEL_PRESETS)))


def _apply_llm_override(cfg: dict) -> dict:
    """Overlay the selected preset onto one stage config (no-op when unset).
    A preset's optional ``"params"`` (e.g. ``{"reasoning_effort": "low"}``) are
    flattened in and reach the chat-model constructor as keyword arguments."""
    if not GENERATOR_LLM:
        return cfg
    spec = resolve_preset(GENERATOR_LLM)
    params = spec.pop("params", None) or {}
    return {**cfg, **spec, **params}


