MAX_THREAD            = 5    # parallel tool calls in the NER agent
# DEFAULT_TOP_K: how many tools the FAISS tool-selector returns per question.
#
# Bumped from 10 → 15 because the partial-name probe showed that on the
# movie graph, top-10 systematically excluded Person tools when the
# question used relational verbs ("feature X in cast", "starring Y",
# "directed by Z"). The eight movie/film-series/award tools dominated the
# top half of the ranking and Person.name fell to ~#11, so the ReAct
# agent never even saw it and resorted to calling `get_movie_eid("Elijah
# Wood")` — a wrong-label tool with predictable empty results. 15 leaves
# slack for the agent to discover the right tool without inflating
# token usage materially.
DEFAULT_TOP_K         = 15   # FAISS tool-selection top-k
TOOL_TOP_K            = 10   # fulltext search top-k per tool call


# ──────────────────────────────────────────────────────────────────────────────
# Method selection — ONE axis names the method directly
# ──────────────────────────────────────────────────────────────────────────────
# METHOD picks the whole pipeline. Five peer methods:
#   no_val_link — feed only {schema}+{question} to the Cypher LLM (lower bound).
#   fcav        — retrieve-then-generate RAG baseline (fcav.py; needs setup_fcav.py).
#   react       — ReAct NER-agent grounder (baseline). Retrieval fixed = fuzzy.
#   graphrag    — Multi-Agent GraphRAG baseline (graphrag.py): generate→execute→
#                 evaluate→repair loop.
#   cyanchor    — OUR method (plan-and-execute grounder; the code internally still
#                 lives in plan_exec.py). Its retrieval is ablatable via the three
#                 RETRIEVAL_* switches below.
#
# RETRIEVAL_* — CyANCHOR's retrieval arms, independently toggleable (≥1 must be on).
# Baselines keep their own FIXED retrieval (react = fuzzy) and IGNORE these switches.
#   RETRIEVAL_FUZZY        per-token fuzzy match, Lucene full-text index, BM25-ranked (default on)
#   RETRIEVAL_VECTOR       in-graph embedding kNN          (default off — needs embeddings)
#   RETRIEVAL_LEVENSHTEIN  APOC normalized edit-distance   (default on)
#
# Paper names. The five components the paper ablates each have one switch here, and the
# paper's name is accepted as an alias of it (component_names.py):
#   RETRIEVAL_FUZZY = TOKEN_LEVEL_FUZZY_MATCH · RETRIEVAL_LEVENSHTEIN = LEVENSHTEIN_RETRIEVAL ·
#   PLAN_EXEC_ESCALATE = ADAPTIVE_SEARCH_CONTROL · CYPHER_SEMANTIC_REPAIR = RESULT_AWARE_QUERY_REPAIR ·
#   PLAN_EXEC_VALUE_SNAP = VALUE_EXISTENCE_GUARD
# The eval_config panel is written with the paper names; eval_run hands the worker the switch
# names, which are also what a run records. For the bare CLI either variable may be exported.
#
# TOOL_TYPE — ReAct baseline tool scope: node | node_rel (released: node, the same
# node-property tools CyANCHOR routes on; CyANCHOR has its own CYANCHOR_TOOL_SCOPE).
#
# Examples:
#   METHOD=cyanchor RETRIEVAL_VECTOR=1 python eval_run.py     # CyANCHOR, all 3 arms
#   METHOD=cyanchor RETRIEVAL_VECTOR=0 python eval_run.py     # CyANCHOR, fuzzy+lev
#   METHOD=graphrag python eval_run.py                        # baseline
# Back-compat: the legacy VAL_LINK_MODE / AGENT_TYPE / RETRIEVAL_TYPE still work
# (val_link+plan_exec → cyanchor, val_link+react → react, hybrid → +vector).
# ──────────────────────────────────────────────────────────────────────────────
# ┌──────────────────────────────────────────────────────────────────────────┐
# │ ⚙ THE EXPERIMENT KNOBS BELOW ARE RECEIVERS — edit them in eval_config.      │
# │   Every `os.getenv("X", <literal>)` experiment knob in this file (METHOD,   │
# │   TOOL_TYPE, RETRIEVAL_*, PLAN_EXEC_*, CYPHER_*, GRAPHRAG_*) is read from    │
# │   an env var that eval_run injects from the eval_config control panel.       │
# │   To change what an EVAL run does, edit the ★ EXPERIMENT PARAMETERS ★ panel  │
# │   in eval_config.py — NOT the literal here. The literal is only the fallback │
# │   for the bare `ner_agent_auto.py` demo/CLI (a shell env var may override    │
# │   it there, which is a CLI convenience). Do not treat it as a 2nd knob.      │
# └──────────────────────────────────────────────────────────────────────────┘
METHOD:    str = os.getenv("METHOD", os.getenv("VAL_LINK_MODE", "cyanchor")).strip().lower()
TOOL_TYPE: str = os.getenv("TOOL_TYPE", "node").strip().lower()
# CyANCHOR-only tool scope (node | node_rel), separate from the ReAct baseline's
# TOOL_TYPE. Released: "node" — relation tools off. The perturbed entities in all
# three benchmarks are node-property values, and the relation-pattern hint injected
# under node_rel repeats the schema already in the prompt: no measurable effect when
# ablated alone (report/ablation_table_gpt-5.6-terra.md).
CYANCHOR_TOOL_SCOPE: str = os.getenv("CYANCHOR_TOOL_SCOPE", "node").strip().lower()
RETRIEVAL_FUZZY       = _component_flag("RETRIEVAL_FUZZY",       "1")   # paper: Token Level Fuzzy Match
RETRIEVAL_VECTOR      = os.getenv("RETRIEVAL_VECTOR",      "0").lower() in ("1", "true", "yes")
RETRIEVAL_LEVENSHTEIN = _component_flag("RETRIEVAL_LEVENSHTEIN", "1")   # paper: Levenshtein Retrieval

_METHODS    = ("no_val_link", "fcav", "react", "graphrag", "cyanchor")
_TOOL_TYPES = ("node", "node_rel")


@dataclass(frozen=True)
class GroundingSpec:
    """Resolved method configuration. ``tool`` applies to react/cyanchor; the arm
    flags (``fuzzy``/``vector``/``lev``) apply to cyanchor only."""
    method: str
    tool:   Optional[str] = None
    fuzzy:  bool = True
    vector: bool = False
    lev:    bool = False

    @property
    def canonical(self) -> str:
        """Internal flat name the pipeline keys on. NOTE: no_val_link maps to the
        legacy ``"no_ner"`` sentinel and react to ``"react_<suffix>"`` because those
        strings are load-bearing (dispatch checks + FAISS index dirs). cyanchor gets
        its own ``"cyanchor_<arms>_<suffix>"`` (arms = f/v/l)."""
        if self.method == "no_val_link":
            return "no_ner"
        if self.method in ("fcav", "graphrag"):
            return self.method
        suffix = "node_only" if self.tool == "node" else "node_rel"
        if self.method == "react":
            return f"react_{suffix}"
        arms = "".join(a for a, on in (("f", self.fuzzy), ("v", self.vector), ("l", self.lev)) if on) or "none"
        return f"cyanchor_{arms}_{suffix}"

    @property
    def retrieval(self) -> Optional[str]:
        """The retrieval mechanism this method actually uses.

        The arm flags are cyanchor-only; the baselines each have their own FIXED
        retrieval and never read them. Deriving this string from the raw flags
        would report the dataclass default (``fuzzy=True``) for fcav/graphrag,
        which is simply wrong — hence the explicit per-method mapping."""
        if self.method == "no_val_link":
            return None                      # grounding bypassed entirely
        if self.method == "fcav":
            return "vector"                  # FAISS over embedded values
        if self.method == "graphrag":
            return "norm-Lev"                # APOC levenshteinSimilarity scan
        if self.method == "react":
            return "fuzzy"                   # fixed BM25/Lucene
        return "+".join(a for a, on in (("fuzzy", self.fuzzy), ("vector", self.vector),
                                        ("lev", self.lev)) if on) or None

    @property
    def label(self) -> str:
        """Human-readable name for eval records / reports."""
        if self.method == "no_val_link":
            return "No Val Link"
        if self.method == "fcav":
            return "FCAV"
        if self.method == "graphrag":
            return "GraphRAG"
        if self.method == "react":
            return "ReAct"          # tool scope is TOOL_TYPE (released: node), recorded in run_config.knobs, not in the name
        tl = "Node" if self.tool == "node" else "Node + Rel"
        arms = "+".join(a for a, on in (("fuzzy", self.fuzzy), ("vector", self.vector), ("lev", self.lev)) if on)
        return f"CyANCHOR [{arms}] ({tl})"


def _spec_from_env() -> GroundingSpec:
    m = METHOD
    # ── Back-compat with the old four-axis scheme ────────────────────────────
    if m == "val_link":
        ag = os.getenv("AGENT_TYPE", "plan_exec").strip().lower()
        m = "cyanchor" if ag in ("plan_exec", "cyanchor") else "react"
    elif m == "plan_exec":
        m = "cyanchor"
    if m not in _METHODS:
        raise ValueError(f"METHOD must be one of {_METHODS}, got {METHOD!r}.")
    if m in ("no_val_link", "fcav", "graphrag"):
        return GroundingSpec(m)
    tool = TOOL_TYPE if TOOL_TYPE in _TOOL_TYPES else "node"
    if m == "react":
        return GroundingSpec("react", tool=tool)
    # cyanchor: its own scope knob (the baseline's TOOL_TYPE must not move with it)
    tool = CYANCHOR_TOOL_SCOPE if CYANCHOR_TOOL_SCOPE in _TOOL_TYPES else "node"
    # cyanchor: read the three retrieval arms (legacy RETRIEVAL_TYPE=hybrid → +vector)
    fuzzy, vector, lev = RETRIEVAL_FUZZY, RETRIEVAL_VECTOR, RETRIEVAL_LEVENSHTEIN
    if os.getenv("RETRIEVAL_TYPE", "").strip().lower() == "hybrid":
        vector = True
    if not (fuzzy or vector or lev):
        raise ValueError("CyANCHOR needs at least one RETRIEVAL_* arm enabled.")
    return GroundingSpec("cyanchor", tool=tool, fuzzy=fuzzy, vector=vector, lev=lev)


def _spec_from_canonical(name: str) -> GroundingSpec:
    """Parse a canonical internal name back into a spec. Used by internal callers
    that thread the flat string (e.g. per-mode FAISS index selection)."""
    n = (name or "").strip().lower()
    if n in ("", "no_ner", "no_val_link"):
        return GroundingSpec("no_val_link")
    if n in ("fcav", "graphrag"):
        return GroundingSpec(n)
    if n.startswith("react_"):
        suf = n[len("react_"):]
        return GroundingSpec("react", tool="node" if suf == "node_only" else "node_rel")
    if n.startswith("cyanchor_") or n.startswith("plan_exec_"):
        rest = n.split("_", 1)[1] if n.startswith("cyanchor_") else n[len("plan_exec_"):]
        hybrid = rest.endswith("_hybrid")          # legacy plan_exec_..._hybrid
        rest = rest[: -len("_hybrid")] if hybrid else rest
        for suf in ("node_only", "node_rel"):
            if rest.endswith(suf):
                tool = "node" if suf == "node_only" else "node_rel"
                arms = rest[: -(len(suf) + 1)]      # leading f/v/l, or "" for legacy
                if n.startswith("plan_exec_"):      # legacy: fuzzy + (vector if hybrid)
                    return GroundingSpec("cyanchor", tool=tool, fuzzy=True, vector=hybrid, lev=False)
                return GroundingSpec("cyanchor", tool=tool,
                                     fuzzy="f" in arms, vector="v" in arms, lev="l" in arms)
    raise ValueError(f"Unknown grounding mode {name!r}.")


def resolve_spec(mode=None) -> GroundingSpec:
    """Resolve the active :class:`GroundingSpec`.

    *mode* may be a :class:`GroundingSpec` (returned as-is), a canonical internal
    name string (parsed — internal callers), or ``None`` (read from METHOD + the
    RETRIEVAL_*/TOOL_TYPE env vars — the user-facing entry point)."""
    if isinstance(mode, GroundingSpec):
        return mode
    if mode:
        return _spec_from_canonical(mode)
    return _spec_from_env()

# RAG baseline: the ReAct NER agent restricted to a SINGLE tool-call round and
# with the tool-result backfill DISABLED. It uses the same (node + relation)
# tool set as `full`, but the agent gets one think→act→observe cycle and must
# then answer — no iterative refinement, no safety net. This isolates "what one
# retrieval round of an LLM agent recovers" as a lower-effort baseline against
# the full agentic `full` / `node_only` modes (which loop + backfill).
# RAG_RECURSION_LIMIT caps the LangGraph supersteps: agent → tools → agent ≈ 3.
RAG_RECURSION_LIMIT = 1

# plan_exec baseline: a deterministic plan-and-execute grounder (no ReAct loop).
#   PLAN     — one LLM call decomposes the question into entity mentions, each
#              tagged node|relation + a short type descriptor.
#   EXECUTE  — per mention: route to the matching tool via the tool-VectorDB
#              (by descriptor), then search_tool(mention) for the top-K
#              canonical values (node mentions) / emit the relationship pattern
#              (relation mentions). No per-tool get_entity re-extraction.
#   GENERATE — the per-mention candidate lists are handed verbatim to the
#              Cypher LLM, which does the value-linking while writing Cypher.
# Contrasts with `full`: per-entity tool routing (no top-k tool crowding), no
# get_entity intermediate layer, and candidates (not a single forced pick) are
# given to the generator. Retrieval stays fuzzy (no value-embedding index).
PLAN_EXEC_TOOLS_PER_ENTITY = int(os.getenv("PLAN_EXEC_TOOLS_PER_ENTITY", "2"))    # tools routed per extracted mention
PLAN_EXEC_VALUES_PER_TOOL  = int(os.getenv("PLAN_EXEC_VALUES_PER_TOOL", "10"))   # top-K canonical values searched per tool (fuzzy modes)

# plan_exec_node_rel_hybrid: per tool, union fuzzy top-K with vector top-K
# candidates (fuzzy first, vector fills the tail). Tests whether in-graph
# embedding recall recovers the alias/abbrev cases fuzzy misses.
PLAN_EXEC_HYBRID_FUZZY_K  = 10    # fuzzy candidates per tool
PLAN_EXEC_HYBRID_VECTOR_K = 5     # embedding (vector-index) candidates per tool

# plan_exec corrective-retrieval escalation (orthogonal to fuzzy/hybrid):
# after the initial retrieval, an LLM judge checks whether the entity mention
# is actually grounded in the candidates retrieved so far. If not, retrieval is
# escalated with a diminishing budget — FIRST deeper into the already-used
# tool(s) (the canonical value may rank below the initial top-K), THEN to the
# next-ranked tools — re-judging after each step and stopping once grounded or
# the budget is spent. Only fires on a miss, so well-grounded entities pay just
# one judge call and no extra retrieval (avoids the candidate-noise penalty of
# blanket top-K increases).
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
PLAN_EXEC_ESCALATE        = _component_flag("PLAN_EXEC_ESCALATE", "1")          # paper: Adaptive Search Control
PLAN_EXEC_MAX_ITER        = int(os.getenv("PLAN_EXEC_MAX_ITER", "3"))           # max escalation rounds per mention
PLAN_EXEC_ESCALATE_BUDGET = tuple(int(x) for x in os.getenv("PLAN_EXEC_ESCALATE_BUDGET", "5,3,1").split(","))   # values added per successive round (deepen step)
PLAN_EXEC_ROUTE_FETCH     = int(os.getenv("PLAN_EXEC_ROUTE_FETCH", "6"))           # tools FAISS-routed per mention (initial + escalation pool)
# In escalation the LLM judge picks the next action from: done | value (deepen
# the used field) | a specific Label.property field to ADD (chosen from the menu
# of available node fields). 'value' deepens fuzzy in the fuzzy mode and BOTH
# fuzzy+vector in hybrid. A newly chosen field gets a full initial-style fetch.

# ──────────────────────────────────────────────────────────────────────────────
# Multi-Agent GraphRAG baseline  (VAL_LINK_MODE=graphrag — see graphrag.py)
# ──────────────────────────────────────────────────────────────────────────────
# A self-correcting generate→execute→evaluate loop (NO pre-grounding stage):
#
#   GENERATE  — the Cypher LLM writes a query from {schema}+{question} (round 1
#               has no entity hints; later rounds get the aggregated feedback).
#   EXECUTE   — run the query; classify (error | empty | rows).
#   EVALUATE  — an LLM judge labels the outcome:
#                 accept                        → format & return the answer.
#                 incorrect|illogical|incomplete→ hand the semantic/logical
#                                                 feedback straight to GENERATE.
#                 error|empty                   → STRUCTURAL repair: extract the
#                   query's node labels, property–value pairs and relationship
#                   patterns, verify each against the DB, retrieve normalized-
#                   Levenshtein candidate replacements for the invalid values,
#                   aggregate execution+semantic+validation feedback, regenerate.
#   …iterate up to GRAPHRAG_MAX_ITER rounds, then return the best attempt.
#
# Generator reuses CYPHER_LLM_CONFIG; evaluator/selector reuse NER_LLM_CONFIG.
# Selection: METHOD = "graphrag" in eval_config.py for the eval harness (eval_run
# injects it and ignores shell variables); VAL_LINK_MODE=graphrag still works for
# ner_agent_auto.py.
GRAPHRAG_MAX_ITER       = 4     # generate→execute→correct rounds (paper = 4)
GRAPHRAG_CANDIDATE_K    = 10    # Levenshtein candidates retrieved per invalid value
GRAPHRAG_LEV_THRESHOLD  = 0.0   # min normalized-Levenshtein sim to keep a candidate (0 = keep all)
# Candidate replacements are ranked by normalized Levenshtein over the (label,
# property) value set — server-side via APOC (apoc.text.levenshteinSimilarity);
# if APOC is unavailable we scan distinct values in Python, capped at this many.
GRAPHRAG_SCAN_CAP       = 50000
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
GRAPHRAG_EMPTY_IS_WRONG = os.getenv("GRAPHRAG_EMPTY_IS_WRONG", "1").lower() in ("1", "true", "yes")
GRAPHRAG_LLM_EVALUATOR  = os.getenv("GRAPHRAG_LLM_EVALUATOR", "1").lower() in ("1", "true", "yes")

# ──────────────────────────────────────────────────────────────────────────────
# Cypher execution-error retry  (applies to the val_link Cypher stage only)
# ──────────────────────────────────────────────────────────────────────────────
# After value-linking finishes and the Cypher LLM has written a query, if that
# query FAILS TO EXECUTE (syntax/runtime error), feed the Neo4j error message
# back to the Cypher LLM and have it rewrite the query — up to
# CYPHER_RETRY_MAX_ROUNDS total attempts. This is error-driven only: an empty
# result is NOT a retry trigger (there is no error message to act on).
#
# Scope: only the value-linking pipeline (VAL_LINK_MODE=val_link, i.e. the
# ReAct / Plan&Exec grounders). The baselines (no_val_link, fcav) keep using
# GraphCypherQAChain unchanged; graphrag has its own loop.
# On a DB execution error the repair is a SINGLE error-message-informed CoT pass
# (reason about the error + required structure, then rewrite) — NOT N blind
# retries (blind re-rolls reproduce the same structural mistake; one CoT repair
# corrects more per round at far lower latency).
#   0 = use the legacy GraphCypherQAChain path (reproduce pre-retry ablations).
#   1 = single attempt, NO repair (transparent manual generate→execute path —
#       a clean A/B control).
#   2 = 1 generate + 1 CoT repair on error (default).
#   N = 1 generate + up to N-1 CoT repairs.
# NOTE: val_link with this knob uses a direct cypher_llm.invoke path (not
# GraphCypherQAChain). The recorded movie/flight ablations predate it and went
# through GraphCypherQAChain — re-measure the val_link rows for a clean compare.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
CYPHER_RETRY_MAX_ROUNDS = int(os.getenv("CYPHER_RETRY_MAX_ROUNDS", "2"))
# ── CyANCHOR-only semantic repair (generate→execute→EVALUATE-result→repair) ──
# Extends CyANCHOR's existing error-driven CoT retry with a GraphRAG-style
# semantic check on a SUCCESSFULLY-EXECUTED result: an LLM evaluator judges
# accept / incorrect / illogical / incomplete (empty counts as wrong when
# CYPHER_EMPTY_IS_WRONG), and on a defect CyANCHOR regenerates — keeping its
# grounding injection + CoT, plus the semantic feedback. CyANCHOR ONLY (the
# shared helper is gated by a per-call flag); react/graphrag/baselines untouched.
# Anti-oscillation: the final query is the first ACCEPTED attempt, else the first
# executable attempt (so it can only match-or-beat the no-repair result, never
# silently drift below it). Default on (finished optimizations ship default-on).
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
CYPHER_SEMANTIC_REPAIR  = _component_flag("CYPHER_SEMANTIC_REPAIR", "1")   # paper: Result Aware Query Repair
CYPHER_REPAIR_MAX_ROUNDS = int(os.getenv("CYPHER_REPAIR_MAX_ROUNDS", "4"))
# Default OFF (2026-09): the empty-result trigger showed zero contribution in a
# 4-graph paired ablation — with grounding front-loaded, residual empties are
# mostly legitimately-empty answers and re-generation only churns.
CYPHER_EMPTY_IS_WRONG    = os.getenv("CYPHER_EMPTY_IS_WRONG", "0").lower() in ("1", "true", "yes")
# Retry is error-driven only — an empty result does NOT trigger a rewrite. An
# empty result is not evidence of a wrong query (the answer may legitimately be
# empty), and on this benchmark the dominant failure is "wrong-but-non-empty"
# grounding, which execution feedback can't detect anyway. (Measured: empty-retry
# had 2/20 opportunities, fixed 0, and risks fabricating answers on zero-count
# questions.) The real lever there is semantic verification of the grounded value.

# ──────────────────────────────────────────────────────────────────────────────
# Plan&Exec value-snap  (post-generation grounding guard for the SELECTION error)
# ──────────────────────────────────────────────────────────────────────────────
# Targets the "retrieved-but-not-used" grounding failure: plan_exec DID retrieve
# the canonical value, but the Cypher LLM copied the question's perturbed surface
# form into the WHERE clause (e.g. WHERE p.name = "Tmo Hooper" while "Tom Hooper"
# sat in the candidate list). After generation, for each entity value the query
# uses:
#   • EXISTENCE GATE — if the value EXISTS in the DB, never touch it (so correct/
#     normal queries are structurally safe — they use real values).
#   • if it does NOT exist (the predicate provably matches 0 rows), one batched
#     LLM call picks the matching candidate from plan_exec's already-retrieved
#     candidates, or NONE. The pick is validated to be in the candidate list
#     (guards hallucination); NONE → no snap (recall misses are left for richer
#     retrieval, never fabricated).
# Only `=` / inline-map string literals are considered (not =~ / CONTAINS, which
# are intentional partials). plan_exec only; fires only on non-existent values,
# so the extra LLM call is rare. Set to 0 to disable.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
PLAN_EXEC_VALUE_SNAP = _component_flag("PLAN_EXEC_VALUE_SNAP", "1")   # paper: Value Existence Guard

# Latency: skip the escalation loop for a mention that is ALREADY cleanly
# grounded — i.e. a retrieved candidate exact/substring-matches the mention
# (the free, no-LLM check from _judge_grounded's fast path). Only skips work
# that escalation would not have improved, so it's ~EA-neutral. Set 0 to ablate.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
PLAN_EXEC_SKIP_GROUNDED = os.getenv("PLAN_EXEC_SKIP_GROUNDED", "1").lower() in ("1", "true", "yes")
# Pre-generation select-or-abstain judge on non-cheaply-grounded node mentions
# (plan_exec._judge_select). On in the released configuration.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
# Ablated alone it has no measurable main effect on EA or PSJS (4 graphs, 2 backbones;
# full pole graph 2026-09-29: +0.6 pts, p=0.46 over 1,283 paired questions) and no
# measurable reduction of confidently-wrong answers (report/judge_failure_modes.md); it
# interacts with the escalation loop, which supplies the candidates it selects from.
# Costs one LLM call per non-cheaply-grounded mention. Candidates are DB values either way.
PLAN_EXEC_SELECT_JUDGE = os.getenv("PLAN_EXEC_SELECT_JUDGE", "1").lower() in ("1", "true", "yes")
# Latency: run the per-mention EXECUTE/escalation concurrently (mentions are
# independent — same calls, same results, just not serialized). Capped by
# MAX_THREAD. Set 0 to force serial.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
PLAN_EXEC_PARALLEL_MENTIONS = os.getenv("PLAN_EXEC_PARALLEL_MENTIONS", "1").lower() in ("1", "true", "yes")

# CyANCHOR retrieval arms are the three RETRIEVAL_FUZZY / RETRIEVAL_VECTOR /
# RETRIEVAL_LEVENSHTEIN switches (defined in the Method-selection block above).
# The Levenshtein arm is a server-side APOC scan (apoc.text.levenshteinSimilarity)
# over each (label,property) value set; cheap on small graphs (flight ~1.7k), but
# O(N) per mention on large graphs (movie ~218k) — gate at movie scale.
# ⚙ eval receiver — edit in the eval_config panel, not here (literal = demo/CLI fallback).
RETRIEVAL_LEVENSHTEIN_K = int(os.getenv("RETRIEVAL_LEVENSHTEIN_K", "10"))  # candidates from the Lev arm

